package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"net/url"
	"os"
	"path"
	"strings"
	"time"
)

// Config is the proxy's entire knowledge of the outside world, generated by
// Nix at launch (or written by hand for standalone use). Credentials are
// named by environment variable and never written into the file.
type Config struct {
	// Listen is the TCP address to serve on, e.g. "127.0.0.1:18080".
	Listen string `json:"listen"`
	// Mode is "enforce" (deny off-allowlist traffic) or "log" (allow it,
	// audit it as would_deny — the shadow rung of the policy ladder).
	Mode string `json:"mode"`
	// AllowlistFile holds CONNECT host[:port] patterns, in the same file
	// format as allowlists/.
	AllowlistFile string `json:"allowlistFile"`
	// AuditLog is the JSONL decision log path; empty logs to stderr.
	AuditLog string `json:"auditLog"`
	// PortFile, when set, receives the bound listen address once the proxy
	// is serving — the launcher binds us to port 0 and reads this instead of
	// parsing logs.
	PortFile string `json:"portFile"`
	// UsageFile, when set, is replaced after each metered response with what
	// each endpoint has spent: requests, refusals, tokens, its budget and
	// whether that is exhausted. The audit log stays one decision per line.
	UsageFile string `json:"usageFile"`
	// Endpoints are the reverse-proxied LLM APIs.
	Endpoints []Endpoint `json:"endpoints"`
}

// Endpoint is one reverse-proxied API. The guest's BASE_URL points at Prefix
// on this proxy; the proxy originates genuine TLS to Upstream and validates
// the real certificate — no CA in the guest trust store, no interception
// anywhere.
type Endpoint struct {
	// Prefix is the path the guest is configured with, e.g. "/anthropic".
	Prefix string `json:"prefix"`
	// Upstream is the real origin, e.g. "https://api.anthropic.com".
	Upstream string `json:"upstream"`
	// KeyEnv names the env var holding the credential to inject. Empty is
	// passthrough (OAuth mode): the client's own token crosses untouched,
	// because the proxy cannot hold a credential the client mints itself.
	KeyEnv string `json:"keyEnv"`
	// KeyFile is the other way to hold a credential: an absolute path to a
	// JSON file {"value": "…", "expires_at": "<RFC 3339>"}, re-read on every
	// request, for a credential that expires and is renewed by someone else
	// (a refresher beside the proxy). Exclusive with KeyEnv.
	//
	// ⛔ Missing, unreadable, malformed, empty or past expires_at: the
	// request is refused (503), in both modes. It never falls back to
	// passthrough, which would send the client's own token, nor to a
	// credential it held before.
	KeyFile string `json:"keyFile"`
	// Header names the credential header: "x-api-key",
	// "x-goog-api-key", … — or "authorization", sent as a Bearer token.
	Header string `json:"header"`
	// AllowedPaths are the upstream paths permitted once Prefix is stripped:
	// "/v1/messages" covers that path and everything below it,
	// "/v1/messages$" only the exact path. Everything else is denied: every
	// endpoint is an attack surface, and even with our own key the API is an
	// exfiltration channel (upload to a files endpoint and the data is gone)
	// — "allowlists function as capability grants."
	AllowedPaths []string `json:"allowedPaths"`
	// Usage names how to read token usage out of responses ("anthropic": the
	// Messages API, streamed or not). Empty: tokens are not counted.
	Usage string `json:"usage"`
	// Budget, when set, caps this endpoint for the session: past it, requests
	// are refused (403) and audited as over_budget, in both modes — a budget
	// is a spending limit, not an egress rule the shadow rung would relax.
	Budget *Budget `json:"budget"`

	upstreamURL *url.URL
	meter       meter
	key         string
	// now is the clock KeyFile's expiry is checked against.
	now func() time.Time
}

// version is stamped at build time from ./VERSION (-X main.version=…).
var version = "dev"

func main() {
	configPath := flag.String("config", "", "path to the JSON config")
	showVersion := flag.Bool("version", false, "print the version and exit")
	flag.Parse()
	if *showVersion {
		fmt.Println("egress-proxy", version)
		return
	}
	if *configPath == "" {
		fmt.Fprintln(os.Stderr, "egress-proxy: -config is required")
		os.Exit(64)
	}
	p, cfg, err := load(*configPath)
	if err != nil {
		fmt.Fprintln(os.Stderr, "egress-proxy:", err)
		os.Exit(1)
	}
	ln, err := net.Listen("tcp", cfg.Listen)
	if err != nil {
		fmt.Fprintln(os.Stderr, "egress-proxy:", err)
		os.Exit(1)
	}
	// The launcher parses this line to learn the bound port, so keep it
	// stable: "egress-proxy listening on <addr> (mode=<mode>)".
	fmt.Printf("egress-proxy listening on %s (mode=%s)\n", ln.Addr(), cfg.Mode)
	if cfg.PortFile != "" {
		if err := os.WriteFile(cfg.PortFile, []byte(ln.Addr().String()+"\n"), 0o600); err != nil {
			fmt.Fprintln(os.Stderr, "egress-proxy:", err)
			os.Exit(1)
		}
	}
	// The usage file exists from the start: a reader at exit finds one even
	// when no request came.
	p.writeUsage()
	srv := &http.Server{Handler: p, ReadHeaderTimeout: 30 * time.Second}
	if err := srv.Serve(ln); err != nil {
		fmt.Fprintln(os.Stderr, "egress-proxy:", err)
		os.Exit(1)
	}
}

func load(path string) (*Proxy, *Config, error) {
	cfg, err := readConfig(path)
	if err != nil {
		return nil, nil, err
	}
	allow, err := loadAllowlist(cfg.AllowlistFile)
	if err != nil {
		return nil, nil, err
	}

	endpoints := make([]*Endpoint, 0, len(cfg.Endpoints))
	for i := range cfg.Endpoints {
		ep := &cfg.Endpoints[i]
		if err := ep.init(); err != nil {
			return nil, nil, fmt.Errorf("endpoint %q: %w", ep.Prefix, err)
		}
		endpoints = append(endpoints, ep)
	}

	auditW, err := openAuditLog(cfg.AuditLog)
	if err != nil {
		return nil, nil, err
	}

	p := &Proxy{
		mode:          cfg.Mode,
		allow:         allow,
		endpoints:     endpoints,
		audit:         slog.New(slog.NewJSONHandler(auditW, nil)),
		transport:     &http.Transport{Proxy: http.ProxyFromEnvironment},
		upstreamProxy: http.ProxyFromEnvironment,
		usageFile:     cfg.UsageFile,
	}
	return p, cfg, nil
}

func readConfig(path string) (*Config, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("config: %w", err)
	}
	var cfg Config
	dec := json.NewDecoder(strings.NewReader(string(raw)))
	dec.DisallowUnknownFields() // a typoed field must not silently no-op
	if err := dec.Decode(&cfg); err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	if cfg.Mode != "enforce" && cfg.Mode != "log" {
		return nil, fmt.Errorf("%s: mode must be \"enforce\" or \"log\", got %q", path, cfg.Mode)
	}
	if cfg.Listen == "" {
		cfg.Listen = "127.0.0.1:0"
	}
	return &cfg, nil
}

func loadAllowlist(path string) (*Allowlist, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("allowlist: %w", err)
	}
	defer func() { _ = f.Close() }()
	allow, err := ParseAllowlist(f)
	if err != nil {
		return nil, fmt.Errorf("allowlist %s: %w", path, err)
	}
	return allow, nil
}

// openAuditLog returns stderr when no path is configured.
func openAuditLog(path string) (*os.File, error) {
	if path == "" {
		return os.Stderr, nil
	}
	f, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o600)
	if err != nil {
		return nil, fmt.Errorf("audit log: %w", err)
	}
	return f, nil
}

func (ep *Endpoint) init() error {
	if !strings.HasPrefix(ep.Prefix, "/") || ep.Prefix == "/" {
		return fmt.Errorf("prefix must start with / and not be the root")
	}
	u, ok := parseOrigin(ep.Upstream)
	if !ok {
		return fmt.Errorf("upstream must be an origin like https://api.example.com, got %q", ep.Upstream)
	}
	ep.upstreamURL = u
	if !isLowerHeaderName(ep.Header) {
		return fmt.Errorf("header must be a lowercase header name like \"x-api-key\" or \"authorization\", got %q", ep.Header)
	}
	if err := validateAllowedPaths(ep.AllowedPaths); err != nil {
		return err
	}
	if err := ep.initBudget(); err != nil {
		return err
	}
	if err := ep.initKeyFile(); err != nil {
		return err
	}
	if ep.KeyEnv != "" {
		ep.key = os.Getenv(ep.KeyEnv)
		if ep.key == "" {
			// A proxy that silently stops injecting is the quiet failure
			// the policy track's rule 2 forbids: fail the launch instead.
			return fmt.Errorf("credential env %s is empty — unset keyEnv explicitly for OAuth mode", ep.KeyEnv)
		}
	}
	return nil
}

func validateAllowedPaths(allowed []string) error {
	if len(allowed) == 0 {
		return fmt.Errorf("allowedPaths must not be empty — an endpoint with no reachable path is a config error, not a default")
	}
	for _, a := range allowed {
		// Requests are matched after path.Clean, so an unclean entry (a
		// trailing slash, a dot segment) could never match: refuse it rather
		// than ship a grant that silently grants nothing — or, for "/",
		// everything.
		p := strings.TrimSuffix(a, "$")
		if !strings.HasPrefix(p, "/") || p == "/" || path.Clean(p) != p || strings.Contains(p, "$") {
			return fmt.Errorf("allowedPaths entry %q must be a clean absolute path below the root, optionally ending in $ for an exact match", a)
		}
	}
	return nil
}

// parseOrigin accepts a bare http(s) origin: scheme and host, no path.
func parseOrigin(s string) (*url.URL, bool) {
	u, err := url.Parse(s)
	if err != nil || (u.Scheme != "http" && u.Scheme != "https") || u.Host == "" || u.Path != "" {
		return nil, false
	}
	return u, true
}

func isLowerHeaderName(h string) bool {
	return h != "" && !strings.ContainsAny(h, " :") && h == strings.ToLower(h)
}
